insert into public.articles (title, category, excerpt, body, date, featured, bg, img)
values (
  'صراع أجيال أم صراع عقول؟',
  'القيادة',
  'في النهاية، أرى من وجهة نظري أن الصراع الذي نشهده اليوم يكمن في اختلاف الذهنيات وليس الأجيال.',
  '<p>لو طلبت من أحد أبنائي إجراء عملية حسابية بسيطة لمعرفة قيمة إجمالي بعض المشتريات، سيلجأ مباشرة لحاسبة جواله ويجري العملية في ثوانٍ معدودةٍ. قد أقترح عليه الاعتماد على مهاراته الحسابية الذهنية لإجراء عملية رياضية سهلة مثل هذه؟! ولكن سيكون رده: ما فائدة التقنية إذن؟</p><p>يمثل هذا الموقف العابر وجهتي نظر مختلفتين. فمن وجهة نظر جيلي يبدو تصرف ابني اتكاليًا، ومن وجهة نظر جيله يبدو ما أقترحه تقليديًا بعض الشيء. هذه التحيزات النمطية قد تظهر بلا وعي منّا عند تعاملنا مع جيلٍ غير جيلنا.</p><h2>ولكن هل من المنصف اتباع هذه التحيزات وإطلاق الأحكام على الأجيال الأخرى؟</h2><p>البعض منا يتحيز لجيله بشدة، ويعتقد أن سنة ميلاده هي ما يحدد هويته، وأن كل خطوة يخطوها يجب أن تتماشى مع ما هو مسموح وغير مسموح عند أبناء جيله. على الصعيد الآخر يشعر البعض بأن جيله لا يمثله، فهو يتمنى لو أنه وُلد في جيل مختلف وعاش تجربته. بحسب تصنيفات الأجيال في المملكة فأنا أنتمي لجيل "الطيبين". جيل يتسم بتقدير قيم العائلة، تحمل المسؤولية والجدية في العمل. عاش شبابه قبل دخول الإنترنت للمملكة، كان يستخدم الدليل الهاتفي للبحث عن رقم صديق، والخرائط الورقية للتنقل أثناء السفر. تأثر جيلي كثيرًا بالوالدين والمعلمين والمشائخ على شاشات التلفاز. وقضى أوقاتًا ممتعة بين كمبيوتر "صخر" والأتاري.</p><h2>ذهنيتك هي ما يمثلك، وليس جيلك</h2><p>رغم امتناني الشديد لجيلي "جيل الطيبين" ودوره الكبير في صقل شخصيتي، إلا أنني أرفض التحيز له في كل الأوقات. والسبب أنني أتبنى قناعة مفادها أن أجيالنا لا تحدد هويتنا، وأن عقولنا هي ما يمثلنا. فأنا مثلًا أرفض بعض ممارسات العمل المرتبطة بأبناء جيلي مثل: التشدد في الآراء، والحزم المفرط. وأجد نفسي في كثير من الأوقات منفتحًا للتعلم من أجيال أخرى، سواءً من أبنائي أو فريق عملي الذي يضم أجيالًا مختلفة مثل "جيل الآيباد" و"جيل الألفية".</p><h2>جيل التغيير</h2><p>الأجيال تُبنى على بعضها، ولا يجب أن نستهين بتجربة جيل سبقنا أو جيل جاء بعدنا، وما مر به من تحديات وخبرات. فكفاح من سبقونا مهد لنا سبلًا كثيرة وأزاح عنا حملًا ثقيلًا، وجرأة وانفتاح من جاء بعدنا فتح لنا أبوابًا مغلقة. وما اختلافاتنا العمرية والاجتماعية والثقافية إلا فرصة للتكامل بما يدعم رحلة تحولنا. فالمملكة تمضي في رحلة تغيير عظيمة لتحقيق رؤية 2030، بقيادة صاحب السمو الملكي ولي العهد الأمير محمد بن سلمان - حفظه الله. والنجاح في رحلة التحول يكون بالتركيز على ما يجمعنا لا ما يفرقنا من خلال الحوار المنفتح والتغلب على تحيزاتنا.</p><p>بنهاية العام الماضي، أطلقنا في مؤسسة محمد بن سلمان "مسك" النسخة السادسة والأضخم من منتدى مسك العالمي بشعار "جيل التغيير" تقوم فكرته على بناء أرض مشتركة تذوب فيها فروقات الأجيال للتكامل والاندماج في جيل واحد هو "جيل التغيير". جيل جديد يضم كل شخص لديه الرغبة بالمساهمة في رحلة التحول بغض النظر عن سنة ميلاده. وخلال مشاركتي في المنتدى تحدثت عن ضرورة هدم الصور النمطية المألوفة التي يحملها كل جيل عن الآخر، والعمل سويًا للاعتراف بأن كل جيل يحمل قيمًا فريدة تضيف لمجتمعاتنا وتطورنا الكثير.</p><h2>ذهنية التحول</h2><p>لقد تنبهت مؤسسة محمد بن سلمان "مسك" إلى ضرورة الاحتفاء باختلاف خبرات الأجيال بدون تفضيل أحدها على الآخر، وتعزيز التكامل بين الأجيال القديمة والجديدة من خلال برامجها وأنشطتها وتسليط الضوء على برنامج "قادة 2030" حيث أعددنا لهذا البرنامج نموذج كفاءة قيادية Leadership Competency Model وحصرنا من خلاله أهم الكفاءات التي يحتاجها القائد لعملية التحول، ليتدرب القادة الشباب على كفاءات متعددة مستلهمة من أجيال مختلفة. ويوضح النموذج أن لكل كفاءة قطبين متضادين، أحدهما يمثل الجيل التقليدي، والآخر يمثل الجيل العصري، بهدف إعداد قادة بذهنيات مرنة تحتوي كلا القطبين لاختيار ما يناسبهم من قيم وأساليب تناسب الموقف. ومن ضمن هذه الكفاءات مثلًا: الموازنة بين "التأني والحذر" الذي يُعزى غالبًا للمدرسة القديمة للقيادة و"المخاطرة والإقدام" الذي يتميز بها الجيل الجديد من القادة. وهذا ما ركزت عليه مشاركتي في النسخة السادسة من مبادرة مستقبل الاستثمار.</p><h2>التقريب بين الأجيال</h2><p>واستكمالًا لجهودنا في التقريب بين الأجيال، أطلقنا في الشهر الماضي في جناح مؤسسة محمد بن سلمان "مسك" - مجلس الشباب - في دافوس على هامش المنتدى الاقتصادي العالمي دراسة بعنوان "تقرير جيل التغيير". استنتجنا منها قائمة بأهم السمات القيادية للتقريب بين الأجيال وكان أهمها:</p><ul><li>السعي إلى فهم أنماط تفكير الأفراد وقيمهم بشكل أفضل.</li><li>القيادة بالاستماع وتعزيز الحوار وتشجيع التعبير عن الاختلاف في الرأي.</li><li>مراعاة الفروقات والاستفادة من نقاط القوة لدى كل جيل لتعزيز شعور جميع الأجيال بالانتماء.</li><li>الانفتاح والتخلص من القوالب النمطية القائمة على العمر أو الجيل.</li><li>الاستثمار في خلق بيئة عمل قائمة على مشاركة المعارف والخبرات وخصوصًا المتعلقة بالقيم المؤسسية وأساليب العمل.</li></ul><p>في النهاية، أرى من وجهة نظري أن الصراع الذي نشهده اليوم يكمن في اختلاف الذهنيات وليس الأجيال. فلو سألني أحدهم ما هو جيلك؟ أجبته بأنني أنتمي لجميع الأجيال بحسب ما يتطلبه الموقف، فتجدني في بعض المواقف أتبنى عقلية "جيل الألفية"، وفي مواقف أخرى أتبنى رأي "جيل الآيباد". وبالتالي يؤلمني كثيرًا الرفض المطلق لجيل كامل بمعتقداته وخبراته وآرائه، ونسف تجارب إنسانية ثرية وحقبة زمنية أضافت لمجتمعاتنا.</p><p>ولهذا أدعوك أيها القارئ إلى تبني "ذهنية التحول" والانضمام "لجيل التغيير" بالانفتاح على الأجيال الأخرى، وبدء حوارات فعالة معها، لأنك بذلك ستعزز فهم العالم من حولك، وتتيح لنفسك أفضل الممارسات من أجيال مختلفة بما يدعم فرص نجاحك المستقبلي، ويقوي حضورك كعضو فعّال في مجتمعك ووطنك.',
  '٢٥ فبراير ٢٠٢٣',
  false,
  'linear-gradient(135deg, #04334c 0%, #0d7377 100%)',
  null
);
